#!/usr/bin/env bash
# Publishes a verified patch. pr mode: commits it to the PR branch, but only if
# the branch still points at the commit the agent worked on (never force-pushes).
# coverage mode: pushes a new branch and opens a pull request.
# Only git and gh run here; no project code is installed or executed.
#   commit.sh <artifacts dir>
#   env: GH_TOKEN MODE AGENT_OUTCOME HEAD_SHA HEAD_REF PR_NUMBER BASE_REF REPOSITORY RUN_URL
set -euo pipefail

dir="$(cd "$1" && pwd)"
here="$(cd "$(dirname "$0")" && pwd)"
output() { echo "$1" >> "$GITHUB_OUTPUT"; }

status="$(node -p "try { require('${dir}/verification.json').status } catch { '' }")"
if [ "$status" != passed ] || [ "$AGENT_OUTCOME" != success ]; then
  echo "Nothing to commit (agent: ${AGENT_OUTCOME:-unknown}, verification: ${status:-not run})."
  output "push=none"
  exit 0
fi

work="$(mktemp -d)"
cd "$work"
git init -q
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
auth="AUTHORIZATION: basic $(printf 'x-access-token:%s' "$GH_TOKEN" | base64 -w0)"
git config "http.https://github.com/.extraheader" "$auth"
git remote add origin "https://github.com/${REPOSITORY}.git"

message() {
  printf '%s\n\n%s\n%s\n\n%s\n' "$1" \
    'Generated by the test-engineer agent and verified in a separate job' \
    '(typecheck, formatting, 3x stability run, full suite with coverage).' \
    "Run: ${RUN_URL}"
}

if [ "$MODE" = pr ]; then
  git fetch -q --depth 1 origin "refs/heads/${HEAD_REF}"
  if [ "$(git rev-parse FETCH_HEAD)" != "$HEAD_SHA" ]; then
    echo "::warning::${HEAD_REF} moved since the agent started; not committing stale tests."
    output "push=stale"
    exit 0
  fi
  git checkout -q FETCH_HEAD
  git apply --index --whitespace=nowarn "${dir}/agent.patch"
  git commit -q -m "$(message "test: add unit tests for changes in #${PR_NUMBER} [agent-tests]")"
  if git push -q origin "HEAD:refs/heads/${HEAD_REF}"; then
    output "push=pushed"
    output "sha=$(git rev-parse HEAD)"
  else
    output "push=stale"
  fi
else
  branch="agent-tests/coverage-${GITHUB_RUN_ID}"
  git fetch -q --depth 1 origin "$HEAD_SHA"
  git checkout -q FETCH_HEAD
  git apply --index --whitespace=nowarn "${dir}/agent.patch"
  git commit -q -m "$(message 'test: raise unit test coverage [agent-tests]')"
  git push -q origin "HEAD:refs/heads/${branch}"
  output "sha=$(git rev-parse HEAD)"
  node "${here}/render-comment.mjs" --dir "$dir" --run-url "$RUN_URL" --agent-outcome "$AGENT_OUTCOME" \
    --push pr-opened --out "${work}/body.md"
  if gh pr create --repo "$REPOSITORY" --base "$BASE_REF" --head "$branch" \
      --title 'test: raise unit test coverage (test-engineer agent)' --body-file "${work}/body.md"; then
    output "push=pr-opened"
  else
    echo "::warning::Pushed ${branch}, but could not open a PR. Enable 'Allow GitHub Actions to create pull requests' in the repository settings."
    output "push=pushed-branch"
  fi
fi
